CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER,role TEXT,content TEXT,provider TEXT,model TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scripts(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER,code TEXT,success INTEGER,output TEXT,error TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
